import { createApp } from './backend/src/app.ts';

const app = createApp();
const base = 'http://localhost/api/v1';
const j = async (r: Response) => {
	const t = await r.text();
	try { return t ? JSON.parse(t) : null; } catch { return t; }
};
const req = (method: string, path: string, body?: unknown) =>
	app.handle(new Request(base + path, {
		method,
		headers: body ? { 'content-type': 'application/json' } : {},
		body: body ? JSON.stringify(body) : undefined,
	}));

// create a habit
let r = await req('POST', '/habits', { name: 'Verify Checkins' });
const habit = await j(r);
console.log('create habit', r.status, habit.id);
const hid = habit.id;

// list checkins (empty)
r = await req('GET', `/habits/${hid}/checkins`);
console.log('list empty', r.status, await j(r));

// mark a day
r = await req('POST', `/habits/${hid}/checkins`, { date: '2026-07-01' });
console.log('mark', r.status, await j(r));

// mark same day again -> 409
r = await req('POST', `/habits/${hid}/checkins`, { date: '2026-07-01' });
console.log('mark dup -> expect 409', r.status, await j(r));

// list checkins (one)
r = await req('GET', `/habits/${hid}/checkins`);
console.log('list one', r.status, await j(r));

// unmark
r = await req('DELETE', `/habits/${hid}/checkins/2026-07-01`);
console.log('unmark -> expect 204', r.status, (await r.text()) || '(empty)');

// unmark again -> 404
r = await req('DELETE', `/habits/${hid}/checkins/2026-07-01`);
console.log('unmark missing -> expect 404', r.status, await j(r));

// mark on missing habit -> 404
r = await req('POST', `/habits/does-not-exist/checkins`, { date: '2026-07-01' });
console.log('mark missing habit -> expect 404', r.status, await j(r));

// bad date format -> 422
r = await req('POST', `/habits/${hid}/checkins`, { date: 'not-a-date' });
console.log('bad date -> expect 422', r.status);

// list on missing habit -> 404
r = await req('GET', `/habits/nope/checkins`);
console.log('list missing habit -> expect 404', r.status);

// cleanup: archive... actually delete the habit row directly
import { getDb } from './backend/src/db/index.ts';
import { habits } from './backend/src/db/schema/index.ts';
import { eq } from 'drizzle-orm';
await getDb().delete(habits).where(eq(habits.id, hid));
console.log('cleanup done');
EOF
